CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(150) NOT NULL, phone VARCHAR(30), date_of_birth DATE, student_id VARCHAR(50), hometown VARCHAR(255), role VARCHAR(20) NOT NULL CHECK (role IN ('STUDENT','LANDLORD','ADMIN')), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','LOCKED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_users_role_status ON users(role,status);
CREATE TABLE landlord_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL UNIQUE REFERENCES users(id), verification_status VARCHAR(30) NOT NULL DEFAULT 'UNVERIFIED', business_name VARCHAR(150), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE properties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES users(id), name VARCHAR(160) NOT NULL, description TEXT, address_line VARCHAR(255) NOT NULL, ward VARCHAR(100), district VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL, latitude NUMERIC(9,6) NOT NULL, longitude NUMERIC(9,6) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_properties_owner ON properties(owner_id); CREATE INDEX idx_properties_location ON properties(city,district);
CREATE TABLE rooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), property_id UUID NOT NULL REFERENCES properties(id), title VARCHAR(180) NOT NULL, description TEXT, monthly_price NUMERIC(14,2) NOT NULL CHECK (monthly_price>=0), area_sqm NUMERIC(8,2) NOT NULL CHECK (area_sqm>0), amenities TEXT NOT NULL DEFAULT '', max_occupants INT NOT NULL DEFAULT 1 CHECK(max_occupants>0), status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','RESERVED','RENTED','HIDDEN')), approval_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(approval_status IN ('DRAFT','PENDING','APPROVED','REJECTED')), rejection_reason TEXT, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_rooms_property ON rooms(property_id); CREATE INDEX idx_rooms_search ON rooms(approval_status,status,monthly_price,area_sqm);
CREATE TABLE room_images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, object_key VARCHAR(500) NOT NULL, content_type VARCHAR(100) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE room_videos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, uploader_id UUID NOT NULL REFERENCES users(id), object_key VARCHAR(500) NOT NULL UNIQUE, upload_token VARCHAR(100) NOT NULL UNIQUE, content_type VARCHAR(100) NOT NULL, size_bytes BIGINT, device_latitude NUMERIC(9,6) NOT NULL, device_longitude NUMERIC(9,6) NOT NULL, gps_accuracy_meters NUMERIC(8,2) NOT NULL, captured_at TIMESTAMPTZ NOT NULL, distance_meters NUMERIC(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'UPLOADING' CHECK(status IN ('UPLOADING','PENDING','APPROVED','REJECTED')), review_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_room_videos_review ON room_videos(status,created_at);
CREATE TABLE conversations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES rooms(id), student_id UUID NOT NULL REFERENCES users(id), landlord_id UUID NOT NULL REFERENCES users(id), student_last_read_at TIMESTAMPTZ, landlord_last_read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(room_id,student_id,landlord_id));
CREATE INDEX idx_conversations_student ON conversations(student_id,updated_at DESC); CREATE INDEX idx_conversations_landlord ON conversations(landlord_id,updated_at DESC);
CREATE TABLE messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id UUID NOT NULL REFERENCES users(id), content TEXT NOT NULL, masked BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_messages_conversation ON messages(conversation_id,created_at);
CREATE TABLE bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), room_id UUID NOT NULL REFERENCES rooms(id), student_id UUID NOT NULL REFERENCES users(id), landlord_id UUID NOT NULL REFERENCES users(id), move_in_date DATE NOT NULL, note TEXT, status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACCEPTED','REJECTED','CANCELLED','COMPLETED')), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_bookings_room_status ON bookings(room_id,status); CREATE INDEX idx_bookings_student ON bookings(student_id,created_at DESC); CREATE INDEX idx_bookings_landlord ON bookings(landlord_id,created_at DESC); CREATE UNIQUE INDEX uq_bookings_one_accepted_room ON bookings(room_id) WHERE status='ACCEPTED';
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id), student_id UUID NOT NULL REFERENCES users(id), landlord_id UUID NOT NULL REFERENCES users(id), amount NUMERIC(14,2) NOT NULL CHECK(amount>0), currency VARCHAR(3) NOT NULL DEFAULT 'VND', status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','HELD','RELEASED','REFUNDED','FAILED')), provider VARCHAR(30) NOT NULL DEFAULT 'MOCK', provider_reference VARCHAR(100) NOT NULL UNIQUE, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_payments_booking ON payments(booking_id);
CREATE TABLE landlord_verifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), landlord_id UUID NOT NULL REFERENCES users(id), legal_name VARCHAR(150) NOT NULL, identity_number_masked VARCHAR(50) NOT NULL, address TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','AI_PROCESSED','NEEDS_REVIEW','APPROVED','REJECTED')), provider VARCHAR(50) NOT NULL, simulated BOOLEAN NOT NULL DEFAULT true, extracted_data TEXT, anomaly_reasons TEXT, admin_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_verifications_review ON landlord_verifications(status,created_at);
CREATE TABLE verification_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), verification_id UUID NOT NULL REFERENCES landlord_verifications(id) ON DELETE CASCADE, document_type VARCHAR(40) NOT NULL, object_key VARCHAR(500) NOT NULL UNIQUE, content_type VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL UNIQUE REFERENCES bookings(id), title VARCHAR(180) NOT NULL, object_key VARCHAR(500), content_type VARCHAR(100), status VARCHAR(30) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','UPLOADED','ANALYZED','PUBLISHED','REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE contract_analyses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), contract_id UUID NOT NULL UNIQUE REFERENCES contracts(id) ON DELETE CASCADE, provider VARCHAR(50) NOT NULL, simulated BOOLEAN NOT NULL DEFAULT true, disclaimer TEXT NOT NULL, review_status VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK(review_status IN ('PENDING','PUBLISHED','REJECTED')), admin_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE contract_risk_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), analysis_id UUID NOT NULL REFERENCES contract_analyses(id) ON DELETE CASCADE, category VARCHAR(80) NOT NULL, severity VARCHAR(20) NOT NULL, explanation TEXT NOT NULL, excerpt TEXT, suggested_question TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ct01_forms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_id UUID NOT NULL REFERENCES users(id), booking_id UUID NOT NULL REFERENCES bookings(id), full_name VARCHAR(150) NOT NULL, date_of_birth DATE NOT NULL, identity_number VARCHAR(30) NOT NULL, phone VARCHAR(30), current_address TEXT NOT NULL, requested_address TEXT NOT NULL, request_content TEXT NOT NULL, additional_data TEXT, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_ct01_student ON ct01_forms(student_id,created_at DESC);
CREATE TABLE disputes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id), created_by UUID NOT NULL REFERENCES users(id), subject VARCHAR(180) NOT NULL, description TEXT NOT NULL, landlord_response TEXT, status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_REVIEW','RESOLVED','REJECTED')), admin_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_disputes_status ON disputes(status,created_at);
CREATE TABLE dispute_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id UUID NOT NULL REFERENCES disputes(id) ON DELETE CASCADE, uploaded_by UUID NOT NULL REFERENCES users(id), object_key VARCHAR(500) NOT NULL UNIQUE, content_type VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), type VARCHAR(50) NOT NULL, title VARCHAR(180) NOT NULL, content TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_notifications_user ON notifications(user_id,read_at,created_at DESC);
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, resource_type VARCHAR(80) NOT NULL, resource_id UUID, details TEXT, ip_address VARCHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_logs_resource ON audit_logs(resource_type,resource_id); CREATE INDEX idx_audit_logs_created ON audit_logs(created_at DESC);
